<?php require_once 'config.php';require_login();$pdo=db();$uid=(int)$_SESSION['user']['id'];$role=$_SESSION['user']['role'];$page_title='Meu painel | Kuntima';if($role==='student'){$st=$pdo->prepare("SELECT a.*,s.title,s.organization,s.deadline FROM applications a JOIN scholarships s ON s.id=a.scholarship_id WHERE a.user_id=? ORDER BY a.applied_at DESC");$st->execute([$uid]);$apps=$st->fetchAll();$st=$pdo->prepare("SELECT b.*,m.title,m.price,m.duration_minutes FROM mentorship_bookings b JOIN mentorship_services m ON m.id=b.service_id WHERE b.student_id=? ORDER BY b.session_date DESC");$st->execute([$uid]);$bookings=$st->fetchAll();}require 'includes/header.php'; ?>
<div class="page-heading"><span class="eyebrow" style="color:var(--green)">Área pessoal</span><h1>Olá, <?=e(explode(' ',$_SESSION['user']['name'])[0])?> 👋</h1><p>Acompanha as tuas candidaturas e os pedidos de mentoria num só lugar.</p></div><?php if($role==='student'): ?><div class="dashboard-stats"><div class="stat"><span>Candidaturas submetidas</span><strong><?=count($apps)?></strong></div><div class="stat"><span>Pedidos de mentoria</span><strong><?=count($bookings)?></strong></div><div class="stat"><span>Perfil</span><strong style="font-size:20px">Estudante</strong></div></div><div class="section" style="padding-top:5px"><div class="section-head"><div><h2>As minhas candidaturas</h2><p>O estado é actualizado pela administração.</p></div><a class="btn-primary" href="bolsas.php">Explorar bolsas</a></div><?php if($apps): ?><div class="table-wrap"><table><thead><tr><th>Bolsa</th><th>Instituição</th><th>Data</th><th>Estado</th></tr></thead><tbody><?php foreach($apps as $a): ?><tr><td><?=e($a['title'])?></td><td><?=e($a['organization'])?></td><td><?=e(date('d/m/Y',strtotime($a['applied_at'])))?></td><td><span class="status <?=e($a['status']==='approved'?'approved':($a['status']==='rejected'?'rejected':'pending'))?>"><?=e(['submitted'=>'Submetida','reviewing'=>'Em análise','approved'=>'Aprovada','rejected'=>'Não aprovada'][$a['status']]??$a['status'])?></span></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">Ainda não submeteste candidaturas. <a class="text-link" href="bolsas.php">Explora as bolsas disponíveis.</a></div><?php endif; ?></div><div class="section"><div class="section-head"><div><h2>Os meus pedidos de mentoria</h2><p>Os pedidos aguardam confirmação da equipa.</p></div><a class="text-link" href="mentoria.php">Ver serviços →</a></div><?php if($bookings): ?><div class="table-wrap"><table><thead><tr><th>Serviço</th><th>Data pretendida</th><th>Valor indicativo</th><th>Estado</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><?=e($b['title'])?></td><td><?=e(date('d/m/Y H:i',strtotime($b['session_date'])))?></td><td><?=number_format((float)$b['price'],0,',','.')?> Kz</td><td><span class="status <?=e($b['status']==='confirmed'?'approved':'pending')?>"><?=e(['requested'=>'Pendente','confirmed'=>'Confirmada','completed'=>'Concluída','cancelled'=>'Cancelada'][$b['status']]??$b['status'])?></span></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">Ainda não pediste nenhuma sessão de mentoria.</div><?php endif; ?></div><?php elseif($role==='admin'): ?><div class="features"><div class="feature"><h3>Administração</h3><p>Gere as candidaturas e os pedidos de mentoria.</p><a class="text-link" href="admin.php">Abrir administração →</a></div><div class="feature"><h3>Oportunidades</h3><p>Consulta as bolsas publicadas.</p><a class="text-link" href="bolsas.php">Ver bolsas →</a></div></div><?php else: ?><div class="empty">A tua conta está registada como mentor. A gestão de serviços pode ser adicionada numa próxima versão. <a class="text-link" href="mentoria.php">Ver serviços públicos</a></div><?php endif; ?><?php require 'includes/footer.php'; ?>
